
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_mpw91_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_mpw91", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.324563284669153e+00, -4.242839073634166e+00, -4.128412565572518e+00, -3.970088429546130e+00, -3.754736562245218e+00, -3.468915933037048e+00, -3.102656280340442e+00, -2.656142418819279e+00, -2.148143119798905e+00, -1.617659686280275e+00, -1.097062851636014e+00, -7.122780656860321e-01, -6.043733955246290e-01, -5.042693243081076e-01, -3.725877927307611e-01, -2.462043063115155e-01, -1.447930738723532e-01, -4.925910665850310e-02, -1.260647582023428e-03, -3.148792652837283e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


